// Extract error and execution metadata
const exec = $json.execution || {};
const wf = $json.workflow || {};
const err = exec.error || {};

const workflowName = wf.name || "Unknown Workflow";
const workflowId = wf.id || "N/A";
const executionId = exec.id || "N/A";
const executionUrl = exec.url || ($env.N8N_BASE_URL ? $env.N8N_BASE_URL + '/execution/' + executionId : '');
const lastNode = exec.lastNodeExecuted || "Unknown Node";
const errorMessage = err.message || err.description || "An unexpected error occurred during workflow execution.";
const errorStack = err.stack || err.context?.stack || "No stack trace available.";
const timestamp = new Date().toISOString();

// Recipient email: configurable via environment variable, defaults to hello@datiq.app
const toEmail = $env.ERROR_ALERT_EMAIL || $env.OPS_ALERT_EMAIL || "hello@datiq.app";
const fromEmail = $env.ALERT_EMAIL_FROM || "DatIQ Alerts <alerts@datiq.app>";

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #0c0e12; color: #e2e8f0; margin: 0; padding: 24px; }
    .card { background-color: #14171f; border: 1px solid #2d3748; border-radius: 8px; max-width: 680px; margin: 0 auto; overflow: hidden; }
    .header { background-color: #7f1d1d; border-bottom: 1px solid #991b1b; padding: 18px 24px; }
    .header h2 { margin: 0; font-size: 18px; color: #fecaca; display: flex; align-items: center; gap: 8px; }
    .content { padding: 24px; }
    .meta-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; font-size: 14px; }
    .meta-table td { padding: 8px 0; border-bottom: 1px solid #1e293b; }
    .meta-label { color: #94a3b8; width: 140px; font-weight: 600; }
    .meta-value { color: #f1f5f9; word-break: break-all; }
    .error-box { background-color: #1e1e24; border-left: 4px solid #ef4444; padding: 14px 16px; border-radius: 4px; margin-bottom: 20px; }
    .error-title { font-size: 13px; text-transform: uppercase; letter-spacing: 0.05em; color: #f87171; font-weight: 700; margin-bottom: 6px; }
    .error-msg { font-size: 15px; color: #ffffff; font-family: monospace; white-space: pre-wrap; word-break: break-word; }
    .stack-box { background-color: #090a0f; border: 1px solid #1e293b; border-radius: 4px; padding: 14px; overflow-x: auto; max-height: 280px; }
    .stack-title { font-size: 12px; color: #64748b; font-weight: 600; margin-bottom: 8px; text-transform: uppercase; }
    .stack-trace { font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace; font-size: 12px; color: #cbd5e1; line-height: 1.5; margin: 0; white-space: pre-wrap; }
    .btn { display: inline-block; background-color: #3b82f6; color: #ffffff !important; text-decoration: none; padding: 10px 18px; border-radius: 6px; font-weight: 600; font-size: 14px; margin-top: 16px; }
    .footer { padding: 16px 24px; background-color: #0f1218; border-top: 1px solid #1e293b; font-size: 12px; color: #64748b; text-align: center; }
  </style>
</head>
<body>
  <div class="card">
    <div class="header">
      <h2>🚨 Workflow Execution Failure</h2>
    </div>
    <div class="content">
      <table class="meta-table">
        <tr><td class="meta-label">Workflow:</td><td class="meta-value"><strong>${workflowName}</strong></td></tr>
        <tr><td class="meta-label">Failed Node:</td><td class="meta-value"><code>${lastNode}</code></td></tr>
        <tr><td class="meta-label">Execution ID:</td><td class="meta-value">${executionId}</td></tr>
        <tr><td class="meta-label">Timestamp:</td><td class="meta-value">${timestamp}</td></tr>
      </table>

      <div class="error-box">
        <div class="error-title">Error Details</div>
        <div class="error-msg">${errorMessage}</div>
      </div>

      <div class="stack-box">
        <div class="stack-title">Stack Trace</div>
        <pre class="stack-trace">${errorStack}</pre>
      </div>

      ${executionUrl ? `<p><a href="${executionUrl}" class="btn" target="_blank">View Execution in n8n &rarr;</a></p>` : ''}
    </div>
    <div class="footer">
      DatIQ Automation Reliability Engine &bull; Environment: ${$env.NODE_ENV || 'production'}
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    emailPayload: {
      from: fromEmail,
      to: [toEmail],
      subject: `🚨 [DatIQ Workflow Error] ${workflowName} failed on node "${lastNode}"`,
      html: html
    }
  }
}];
